#include <map>
#include <string>
#include <functional>

// Custom comparator implementing strict weak ordering
struct ReverseStringCmp {
    bool operator()(const std::string& s1, 
                    const std::string& s2) const {
        // s1 comes before s2 if s1 > s2 (reverse alphabetical)
        return s1 > s2;
    }
};

int main() {
    // The map keys will be ordered descendingly
    std::map<std::string, int, ReverseStringCmp> m;
    m["apple"] = 1;
    m["zebra"] = 2;
    // Iteration yields: "zebra", "apple"
}
